'use strict';

class ArchonError extends Error {
    type;
    detail;
    constructor(type, detail) {
        const message = detail ? `${type}: ${detail}` : type;
        super(message);
        this.type = type;
        this.detail = detail;
    }
}
class InvalidDIDError extends ArchonError {
    static type = 'Invalid DID';
    constructor(detail) {
        super(InvalidDIDError.type, detail);
    }
}
class InvalidParameterError extends ArchonError {
    static type = 'Invalid parameter';
    constructor(detail) {
        super(InvalidParameterError.type, detail);
    }
}
class InvalidOperationError extends ArchonError {
    static type = 'Invalid operation';
    constructor(detail) {
        super(InvalidOperationError.type, detail);
    }
}
class KeymasterError extends ArchonError {
    static type = 'Keymaster';
    constructor(detail) {
        super(KeymasterError.type, detail);
    }
}
class UnknownIDError extends ArchonError {
    static type = 'Unknown ID';
    constructor(detail) {
        super(UnknownIDError.type, detail);
    }
}
class LightningNotConfiguredError extends ArchonError {
    static type = 'Lightning not configured';
    constructor(detail) {
        super(LightningNotConfiguredError.type, detail);
    }
}
class LightningUnavailableError extends ArchonError {
    static type = 'Lightning service unavailable';
    constructor(detail) {
        super(LightningUnavailableError.type, detail);
    }
}
// For unit tests
class ExpectedExceptionError extends ArchonError {
    static type = 'Expected to throw an exception';
    constructor() {
        super(ExpectedExceptionError.type);
    }
}

exports.ArchonError = ArchonError;
exports.ExpectedExceptionError = ExpectedExceptionError;
exports.InvalidDIDError = InvalidDIDError;
exports.InvalidOperationError = InvalidOperationError;
exports.InvalidParameterError = InvalidParameterError;
exports.KeymasterError = KeymasterError;
exports.LightningNotConfiguredError = LightningNotConfiguredError;
exports.LightningUnavailableError = LightningUnavailableError;
exports.UnknownIDError = UnknownIDError;
